import{_ as t,o as r,c as n,a3 as i}from"./chunks/framework.B9qR_F1m.js";const a="/bilder/angriff.jpg",c=JSON.parse('{"title":"Angriff","description":"","frontmatter":{},"headers":[],"relativePath":"bereiche/angriff.md","filePath":"bereiche/angriff.md"}'),d={name:"bereiche/angriff.md"};function s(o,e,l,g,u,h){return r(),n("div",null,[...e[0]||(e[0]=[i('<h1 id="angriff" tabindex="-1">Angriff <a class="header-anchor" href="#angriff" aria-label="Permalink to &quot;Angriff&quot;">​</a></h1><p>Der Attack Planner rechnet die Geometrie eines Bodenangriffs <strong>vom Ziel aus</strong>: wo du vom IP abbiegst, wo du hochziehst, wann du einrollst und wo die Bombe fällt. Er zeichnet Profil und Draufsicht und legt eine <strong>Attack Card</strong> aufs Kneeboard.</p><p><img src="'+a+'" alt="Reiter Angriff mit Kennzahlen und Profil" loading="lazy"></p><div class="tip custom-block"><p class="custom-block-title">Nur ein Vorschlag</p><p>Der Planner ändert weder Route noch Cartridge. Er zeigt, wie der Angriff aussehen kann – fliegen und entscheiden tut ihr.</p></div><h2 id="in-drei-schritten" tabindex="-1">In drei Schritten <a class="header-anchor" href="#in-drei-schritten" aria-label="Permalink to &quot;In drei Schritten&quot;">​</a></h2><ol class="steps"><li><b>+ Angriff</b> und das <b>Ziel auf der Karte setzen</b>. Ein Flight kann mehrere Angriffe haben.</li><li><b>Pattern</b> und <b>Vorlage</b> wählen – z. B. <i>Indirect</i> mit <i>CBU 30°</i>.</li><li>Den <b>Run-in-Kurs</b> am Griff auf der Karte drehen oder eintippen, Break links oder rechts.</li></ol><p>Alle weiteren Werte (Höhen, Geschwindigkeiten, Winkel, g) stecken hinter <strong>Details</strong>.</p><h2 id="pattern" tabindex="-1">Pattern <a class="header-anchor" href="#pattern" aria-label="Permalink to &quot;Pattern&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Pattern</th><th>Wofür</th><th>Ablauf</th></tr></thead><tbody><tr><td><strong>Direct</strong></td><td>Pop-up, leicht zu navigieren</td><td>Run-in direkt aufs Ziel, am <strong>AP</strong> Break zur Seite, kurzes Leg, am <strong>PUP</strong> hochziehen, an der <strong>PDA</strong> einrollen, Sturz, Abwurf am <strong>RP</strong></td></tr><tr><td><strong>Indirect</strong></td><td>Pop-up, schwerer vorhersehbar</td><td>Run-in schon versetzt zum Ziel; ab PUP wie Direct</td></tr><tr><td><strong>Wheel</strong></td><td>CAS, Raketen, Gun</td><td>Kreis über dem Ziel in Perch-Höhe, Roll-in nur aus dem erlaubten Sektor</td></tr><tr><td><strong>Toss</strong></td><td>Loft-Abwurf aus dem Tiefflug</td><td>Am PUP mit festem g hochziehen, Abwurf im Steigflug, Escape-Turn zurück in die Tiefe</td></tr><tr><td><strong>Standoff</strong></td><td>JDAM, JSOW, LGB aus der Höhe</td><td>Horizontal bis zur Abwurfdistanz, dann Abflug-Turn</td></tr><tr><td><strong>Standoff + Pull-up</strong></td><td>JDAM aus dem Tiefflug, Maverick-Pop</td><td>Tief anfliegen, hochziehen, in Abwurfhöhe abfangen, Abwurf, wieder tief</td></tr></tbody></table><h2 id="vorlagen" tabindex="-1">Vorlagen <a class="header-anchor" href="#vorlagen" aria-label="Permalink to &quot;Vorlagen&quot;">​</a></h2><p>Startwerte je Waffe, alles änderbar:</p><p><em>Mk-82 LD 20°</em> · <em>Mk-82 HD 30°</em> · <em>CBU 30°</em> · <em>Raketen 10°</em> · <em>Gun 10°</em> · <em>Raketen (Wheel)</em> · <em>Strafe (Wheel)</em> · <em>Mk-82 Toss 30°</em> · <em>Mk-84 Toss 40°</em> · <em>CBU Toss 20°</em> · <em>GBU-12 15.000 ft</em> · <em>JDAM 20.000 ft</em> · <em>JSOW 25.000 ft</em> · <em>JDAM Pull-up 12.000 ft</em> · <em>AGM-65 Pop 3.000 ft</em></p><h2 id="was-du-bekommst" tabindex="-1">Was du bekommst <a class="header-anchor" href="#was-du-bekommst" aria-label="Permalink to &quot;Was du bekommst&quot;">​</a></h2><p><strong>Kennzahlen</strong> oben: Kurs ab IP, Attack Heading, PUP vor Ziel, IP bis PUP (Zeit), PUP bis Abwurf, tiefster Punkt.</p><p><strong>Profil</strong> – Entfernung zum Ziel nach rechts, Höhe nach oben (überhöht), mit allen Punkten: PUP, PDA, Apex, Roll-out, RP und Recovery.</p><p><strong>Draufsicht</strong> – Run-in nach oben, Kurspfeile für <em>Kurs ab IP</em> und <em>Attack Heading</em>, dazu eine Tabelle mit Höhe und Kurs/Distanz zum Ziel für jeden Punkt.</p><p><strong>Karte</strong> – IP → AP → PUP → RP → Ziel und Egress, zusammen mit den freigegebenen Threat-Ringen.</p><p><strong>Attack Card</strong> – eine Kneeboard-Seite pro Angriff nach der Route, mit Profil, Draufsicht, Punkte-Tabelle und Warnungen. Abschaltbar pro Angriff (<strong>Attack Card aufs Kneeboard</strong>). Sie kommt mit der <a href="./lineup-card">Lineup Card</a> in die .miz, als PNG oder PDF.</p><h2 id="begriffe" tabindex="-1">Begriffe <a class="header-anchor" href="#begriffe" aria-label="Permalink to &quot;Begriffe&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Kürzel</th><th>Bedeutung</th></tr></thead><tbody><tr><td><strong>IP</strong></td><td>Initial Point – gut erkennbarer Punkt, an dem der Run-in beginnt</td></tr><tr><td><strong>AP</strong></td><td>Action Point – Beginn des Offset-Turns (Break weg von der Ziellinie)</td></tr><tr><td><strong>PUP</strong></td><td>Pull-Up Point – Beginn des Steigflugs</td></tr><tr><td><strong>PDA</strong></td><td>Pull-Down Altitude – Höhe, an der der Roll-in beginnt</td></tr><tr><td><strong>Apex</strong></td><td>Höchster Punkt, erreicht im Roll-in</td></tr><tr><td><strong>Roll-out</strong></td><td>Flugzeug liegt auf Sturzwinkel und Attack Heading</td></tr><tr><td><strong>RP</strong></td><td>Release Point – Abwurfhöhe und -geschwindigkeit</td></tr><tr><td><strong>Perch</strong></td><td>Ausgangshöhe beim Wheel</td></tr></tbody></table><h2 id="wie-gerechnet-wird" tabindex="-1">Wie gerechnet wird <a class="header-anchor" href="#wie-gerechnet-wird" aria-label="Permalink to &quot;Wie gerechnet wird&quot;">​</a></h2><p>Rein geometrisch, mit konstanter Geschwindigkeit, ohne Flugzeug-Performance und ohne Ballistik – die Abwurfparameter gibst du vor. Faustwerte (einstellbar): Turns mit 4 g, Tracking 4 s, Apex = PDA + 400 ft, Recovery mit 5 g. Beim Toss rechnet im Jet CCRP den echten Abwurf; der PUP ist der Anhalt.</p><div class="warning custom-block"><p class="custom-block-title">In DCS gegenfliegen</p><p>Die Faustwerte sind ein Startpunkt. Fliegt die Werte in DCS nach und passt sie in <strong>Details</strong> an eure Jets und Waffen an.</p></div>',23)])])}const m=t(d,[["render",s]]);export{c as __pageData,m as default};
